package main

import (
	"errors"
	"fmt"
)

func load() (int, error) {
	var err error
	value := 0
	if true {
		value, err = parse() // = assigns the OUTER value and err
		if err != nil {
			return value, err // surface the failure
		}
	}
	return value, err
}

func parse() (int, error) { return 0, errors.New("boom") }

func main() {
	_, err := load()
	fmt.Println("err:", err) // err: boom
}

