package solution

import "errors"

// check rejects negative numbers.
func check(n int) error {
	if n < 0 {
		return errors.New("negative number")
	}
	return nil
}

func Solve(nums []int) (int, error) {
	sum := 0
	var err error
	for _, n := range nums {
		err = check(n) // = assigns the outer err, no shadowing
		if err != nil {
			return 0, err // stop and surface the failure
		}
		sum += n
	}
	return sum, err
}

