func writeConfig(path string, data []byte) error {
	var err error
	if len(data) > 0 {
		err = os.WriteFile(path, data, 0o644) // = assigns the OUTER err
		if err != nil {
			log.Println("write failed:", err)
			return err // propagate the failure
		}
	}
	return err
}

func FirstError(steps []func() error) error {
	for _, step := range steps {
		if err := step(); err != nil { // err is scoped to the if, returned immediately
			return err
		}
	}
	return nil
}
